import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import zlib from 'node:zlib';
import sharp from 'sharp';

// Validate original generated bytes and accepted receipts. The partial mode
// preserves completed files without declaring the full lot produced.
const out='docs/suivi-production/v614';
const checkpointOnly=process.argv.includes('--checkpoint-only');
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const write=(p,v)=>{fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n');};
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const blob=b=>crypto.createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const plan=read(out+'/references/production-plan-v614.json');
const reconciliation=read(out+'/data/main-reconciliation.json');
const main=plan.sourceMainCommit;
if(reconciliation.currentMainCommit!==main||reconciliation.mainNativeAssetCount!==108||!reconciliation.previousProductionCommitIsAncestorOfMain)throw Error('The current main reconciliation is required');
const verifiedAtUtc=new Date().toISOString(),assets=[];
const privatePattern=/\/workspace\/|\/tmp\/|authfile:|download_url|file_uri|[?&](?:token|signature|x-goog-signature)=/i;
for(const item of plan.records){
 const receiptPath=`${out}/receipts/${item.id}.json`;
 if(!fs.existsSync(receiptPath)){if(checkpointOnly)continue;throw Error('Missing receipt: '+item.id);}
 const receiptBytes=fs.readFileSync(receiptPath),receipt=JSON.parse(receiptBytes);
 if(!receipt.visualInspection?.accepted){if(checkpointOnly)continue;throw Error('Unaccepted output: '+item.id);}
 if(privatePattern.test(JSON.stringify(receipt)))throw Error('Private data in public receipt: '+item.id);
 if(receipt.id!==item.id||receipt.repoPngPath!==item.suggestedRepoPngPath||receipt.copiedByteIdentical!==true)throw Error('Native identity or copy proof mismatch: '+item.id);
 const bytes=fs.readFileSync(receipt.repoPngPath),sha256=sha(bytes);
 if(receipt.sha256!==sha256||receipt.bytes!==bytes.length)throw Error('Receipt does not match the PNG: '+item.id);
 const attempt=receipt.attempts?.find(a=>(a.accepted||a.acceptedForCurrentOutput)&&a.sha256===sha256);
 if(!attempt||typeof attempt.promptExact!=='string'||attempt.promptExact.length<100||attempt.promptExact!==receipt.acceptedOutputPromptExact)throw Error('Missing exact accepted prompt: '+item.id);
 if(!receipt.generatedAtUtc||Number.isNaN(Date.parse(receipt.generatedAtUtc))||!receipt.timestampEvidenceFR)throw Error('Missing qualified observation time: '+item.id);
 for(const ref of item.references){
  const submitted=receipt.references?.find(r=>r.id===ref.id);
  if(!submitted||submitted.sha256!==ref.sha256||submitted.repoPath!==ref.repoPath||sha(fs.readFileSync(ref.repoPath))!==ref.sha256)throw Error('Reference bytes or receipt mismatch: '+item.id);
 }
 const meta=await sharp(bytes).metadata();
 if(meta.format!=='png'||meta.width!==1024||meta.height!==1536||meta.channels!==4||!meta.hasAlpha)throw Error('Native format must be 1024×1536 RGBA: '+item.id);
 const {data,info}=await sharp(bytes).raw().toBuffer({resolveWithObject:true});
 let zero=0,solid=0,edgeMax=0;const bounds=[1024,1536,0,0],visible=[1024,1536,0,0];
 for(let y=0;y<info.height;y++)for(let x=0;x<info.width;x++){
  const alpha=data[(y*info.width+x)*4+3];if(alpha===0)zero++;if(alpha>=250)solid++;
  if(alpha){bounds[0]=Math.min(bounds[0],x);bounds[1]=Math.min(bounds[1],y);bounds[2]=Math.max(bounds[2],x+1);bounds[3]=Math.max(bounds[3],y+1);}
  if(alpha>20){visible[0]=Math.min(visible[0],x);visible[1]=Math.min(visible[1],y);visible[2]=Math.max(visible[2],x+1);visible[3]=Math.max(visible[3],y+1);}
  if(x===0||y===0||x===1023||y===1535)edgeMax=Math.max(edgeMax,alpha);
 }
 if(zero<1024*1536*.1||!solid||visible[0]<=0||visible[1]<=0||visible[2]>=1024||visible[3]>=1536)throw Error('Transparency or visible framing failed: '+item.id);
 const margins=[visible[0]/1024,visible[1]/1536,(1024-visible[2])/1024,(1536-visible[3])/1536];
 const limits=[...(receipt.visualInspection.limitationsFR??[]),'Pose fixe ; aucune nouvelle animation ni nouveau placement en scène ; fidélité canonique 1:1 non certifiée.'];
 if(margins.some(m=>m<.08))limits.push('La marge vide cible de 8 % n’est pas atteinte sur tous les côtés ; le contenu visible alpha > 20 reste entièrement dans le cadre.');
 const overrides=item.userOverrides.map(v=>`${v.reasonFR} ${v.field} : ${v.historical} → ${v.effective}.`);
 assets.push({id:item.id,groupId:item.groupId,groupFR:item.groupFR,familyId:item.familyId,variant:10,nameFR:item.nameFR,
  priorStatusFR:'Pas faite',statusFR:'Conservée hors main',sourceWorkbookRow:item.sourceWorkbookRow,
  plannedAppearance:item.historicalBrief,userOverrides:overrides,repoPngPath:receipt.repoPngPath,sha256,bytes:bytes.length,
  width:1024,height:1536,mode:'RGBA',transparentBackground:true,alphaBounds:bounds,contentBoundsAlpha20:visible,
  alphaZeroPixels:zero,alphaSolidPixels:solid,edgeAlphaMax:edgeMax,marginsFraction:margins,targetEightPercentMarginMet:margins.every(m=>m>=.08),
  nativeOutputName:receipt.nativeOutputName,generationMethod:'builtin-imagegen',copiedByteIdentical:true,nativeGitBlobSha:blob(bytes),
  generatedAtUtc:receipt.generatedAtUtc,receiptCreatedAtUtc:receipt.receiptCreatedAtUtc,verifiedAtUtc,
  timestampEvidenceFR:receipt.timestampEvidenceFR,promptExact:receipt.promptExact,acceptedOutputPromptExact:receipt.acceptedOutputPromptExact,
  plannedPromptExact:item.generationPromptFR,plannedPromptIsSubmissionEvidence:false,references:item.references,attempts:receipt.attempts,
  receiptPath,receiptSha256:sha(receiptBytes),provenanceRecovery:{status:'complete-current-final-receipt',historicalAttemptsAreCompleteForFinalOutput:true},
  visualInspection:{...receipt.visualInspection,limitationsFR:[...new Set(limits)]},
  availabilityNow:'verified-in-working-branch',galleryInBranch:true,codexInBranch:true,animated:false,newMapPlacement:false,canonicalFidelityCertified:false});
}
if(new Set(assets.map(a=>a.id)).size!==assets.length||new Set(assets.map(a=>a.sha256)).size!==assets.length)throw Error('Duplicate image or identity');
write(out+'/recovery/native-checkpoint.json',{schemaVersion:'yautja-v614-native-checkpoint-1',verifiedAtUtc,sourceMainCommit:main,
 expectedCount:18,acceptedCount:assets.length,completionState:assets.length===18?'native-images-complete':'native-images-in-progress',
 noteFR:'Les PNG acceptés et leurs reçus sont sauvegardés ; le suivi du lot complet est construit séparément.',assets});
if(checkpointOnly){console.log(JSON.stringify({accepted:assets.length,expected:18}));process.exit(0);}
if(assets.length!==18)throw Error('Exactly 18 accepted native files are required');
const manifest={schemaVersion:'yautja-enforcer-production-v614-1',version:'V6.14',generatedAtUtc:verifiedAtUtc,
 generatedAtMeaning:'manifest-build-time-not-image-generation-time',verifiedAtUtc,sourceMainCommit:main,currentMainCommit:main,
 sourceBranchCommit:plan.sourceBranchCommit,mainReconciliationPath:out+'/data/main-reconciliation.json',pullRequestUrl:reconciliation.successorPullRequestUrl,
 sourceWorkbook:{repoPath:plan.sourceWorkbook.path,sha256:plan.sourceWorkbook.sha256},sourceCatalogue:plan.sourceCatalogue,
 summary:{nativePngFiles:18,groups:18,variants:[10],priorV610PngsRecovered:0,matchingFinalReceiptsRecovered:18,finalReceiptsNotRecovered:0,plannedPromptsAreNotSubmissionEvidence:true},assets};
if(privatePattern.test(JSON.stringify(manifest)))throw Error('Private data in public manifest');
write(out+'/data/production-manifest.json',manifest);

const baselineBytes=fs.readFileSync(plan.sourceMaster.path);
if(sha(baselineBytes)!==plan.sourceMaster.sha256)throw Error('Source master changed after planning');
const baseline=JSON.parse(zlib.gunzipSync(baselineBytes));
const rows=structuredClone(baseline.rows),byId=new Map(rows.map(r=>[r.values.A,r]));
const github='https://github.com/darknigthmare/yautja-la-longue-chasse/blob/';
const promoted=read('docs/suivi-production/v613/data/production-manifest.json').assets;
const mainProof=new Map(reconciliation.assets.map(a=>[a.id,a]));
for(const a of promoted){
 const row=byId.get(a.id),proof=mainProof.get(a.id);
 if(row.values.E!=='Conservée hors main'||proof?.sha256!==a.sha256||!proof.existsInMain)throw Error('Cannot promote unproved V6.13 identity: '+a.id);
 Object.assign(row.values,{E:'Présente dans main',F:'Galerie et codex',G:'Lot V6.13 fusionné dans main via la PR nº 10 ; aucun nouveau placement en scène attesté par cette réconciliation.',
  W:'Oui',AA:'PNG V6.13 natif conservé à l’identique. Fusion de la PR nº 10 vérifiée ; blob et registre présents dans main au commit '+main+'. Galerie et codex raccordés ; pose fixe. Les limites historiques de provenance sont conservées dans le manifeste V6.13.',
  AB:github+main+'/'+a.repoPngPath,AC:github+main+'/app/game/data/enforcerProductionV613.json',AF:a.sha256,
  AH:'PNG et registre V6.13 vérifiés dans main après fusion de la PR nº 10.'});
}
for(const a of assets){
 const row=byId.get(a.id);if(!row||row.values.E!=='Pas faite')throw Error('Identity was not previously unmade: '+a.id);
 Object.assign(row.values,{E:'Conservée hors main',G:`Revoir le lot V6.14 de la PR nº ${reconciliation.successorPullRequestNumber} ; fusion et placement en scène restent à décider.`,
  AA:'PNG V6.14 natif produit et contrôlé. Prompt final et reçu correspondant au SHA256 conservés. Galerie et codex raccordés dans la branche ; pose fixe.',
  AB:github+reconciliation.newBranch+'/'+a.repoPngPath,AC:github+reconciliation.newBranch+'/app/game/data/enforcerProductionV614.json',
  AE:a.repoPngPath,AH:'PNG natif et reçu final vérifiés dans cette livraison ; hors main.',AI:'Identifiant catalogue exact ; nouveau PNG natif inspecté'});
}
const counts={};for(const row of rows)counts[row.values.E]=(counts[row.values.E]??0)+1;
if(JSON.stringify(counts)!==JSON.stringify(reconciliation.statusCountsAfterReconciliationAndV614))throw Error('Unexpected cumulative status counts');
const beforeById=new Map(baseline.rows.map(r=>[r.values.A,r])),changes=[];
for(const row of rows){const old=beforeById.get(row.values.A);for(const c of new Set([...Object.keys(old.values),...Object.keys(row.values)]))if(old.values[c]!==row.values[c])changes.push({id:row.values.A,rowNumber:row.rowNumber,column:c,before:old.values[c]??null,after:row.values[c]??null});}
if(new Set(changes.map(c=>c.id)).size!==54)throw Error('Only the 36 promoted and 18 new rows may change');
const master={schemaVersion:'yautja-master-v614-1',asOfUtc:verifiedAtUtc,sourceMainCommit:main,historicalSourceMainCommit:baseline.sourceMainCommit,
 sourceBranchCommit:plan.sourceBranchCommit,headers:baseline.headers,rowCount:rows.length,statusCounts:counts,rows};
fs.writeFileSync(out+'/data/current-master.json.gz',zlib.gzipSync(JSON.stringify(master)));
write(out+'/data/current-counts.json',{asOfUtc:verifiedAtUtc,total:5120,statusCounts:counts,newProductionCount:18,cumulativeNativePngsAvailable:126,
 newNativePngsInPr:18,priorNativePngsInMain:108,historicalProductionV610Count:36,historicalV610PngsRecovered:0,mainCount:counts['Présente dans main'],
 priorPublishedCommit:plan.sourceBranchCommit,currentMainCommit:main,pullRequestUrl:reconciliation.successorPullRequestUrl,
 remainingEnforcerVariant10Count:0,matchingFinalReceiptsRecovered:18,finalReceiptsNotRecovered:0,priorV613MissingFinalReceipts:21});
write(out+'/validation/master-changes.json',{verifiedAtUtc,changedCells:changes.length,changedRows:54,totalStableIds:5120,changes});
const registryAssets=assets.map(a=>({id:'production-v614:'+a.id+':'+a.sha256.slice(0,12),identityId:a.id,label:a.nameFR+' · 10',packId:'enforcers-v614',
 packLabel:'Enforcers V6.14 · variante 10',version:'V6.14',priority:47,preferredVersion:true,kind:'npc',groupId:a.groupId,groupLabel:a.groupFR,
 role:'enforcers-comics',roleLabel:'Enforcers du comic',lifeStage:a.plannedAppearance.lifeStage,regionId:'',morphotypeId:a.groupId,
 masked:a.groupId==='human-accepted'?'half-mask':a.groupId==='pilot-kok'?'open-face-helmet':'masked',src:a.repoPngPath.replace(/^public/,''),
 width:a.width,height:a.height,bytes:a.bytes,sha256:a.sha256,sourceArchive:'Production native Enforcers V6.14 · 23 octobre 2026',insideArchive:null,
 sourcePath:a.repoPngPath,sourceStatus:'native-produced-visual-reviewed',producerStatus:'verified-in-working-branch',pose:a.plannedAppearance.poseFR,
 motionStatus:'single-pose-static',canonicalFidelity:'not-certified-1-to-1',sourceNote:a.visualInspection.notesFR,sourceLimits:a.visualInspection.limitationsFR,
 supersedesIdentityId:'',supersededByIdentityId:'',fullBody:true,bodyComposition:'single-individual',nativeNature:'native-generated-project-sprite'}));
write('app/game/data/enforcerProductionV614.json',{version:'V6.14',summary:{nativePngFiles:18},packs:[{id:'enforcers-v614',label:'Enforcers V6.14 · variante 10',
 version:'V6.14',priority:47,archive:'Production native · 23 octobre 2026',insideArchive:null,sha256:'',pngEntriesImported:18,recordEntries:18,status:'native-produced-visual-reviewed'}],assets:registryAssets});
console.log(JSON.stringify({produced:18,cumulativeNativePngs:126,changedCells:changes.length,changedRows:54,counts}));
